INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`,
`BroadcastTextId`, `TextRange`, `comment`) VALUES
(99679, 0, 0, 'Roll over the golden rings to keep the barrel\'s energy up!', 42, 0, 100, 0, 0, 0, 0, 0, 'barrel race'),
(99679, 1, 0, 'The barrel has run out of energy and rolls to a stop. Xoxis at the Beach Bar will have another one.', 42, 0, 100, 0, 0, 0, 0, 0, 'barrel race'),
(99679, 2, 0, 'You lost the barrel! Xoxis at the Beach Bar will have another one.', 42, 0, 100, 0, 0, 0, 0, 0, 'barrel race'),
(99715, 0, 0, 'Ahhhhhh', 12, 0, 100, 0, 0, 0, 0, 0, 'Noggenfogger Mycologist (on fire) - panic (live line, said not yelled)'),
(371902, 0, 0, 'Don\'t move...', 12, 0, 100, 0, 0, 0, 0, 0, 'Synix - Goblin Security Screening accepted'),
(371910, 0, 0, 'Ha! Right on time. Roll it behind the bar, I\'ll take it from here.', 12, 0, 100, 1, 0, 0, 0, 0, 'barrel race'),
(371911, 0, 0, 'There she goes! Keep her rolling over the golden rings, sweetheart, or she\'ll run out of steam.', 12, 0, 100, 1, 0, 0, 0, 0, 'barrel race'),
(371911, 1, 0, 'Lost it already? Lucky for you, darling, I always keep a spare. Try to keep this one on the path!', 12, 0, 100, 1, 0, 0, 0, 0, 'barrel race'),
(371917, 0, 0, 'Da Captain card! An authority figure leadin\' an expedition or a journey. Da journey is figurative, though in ya case I\'m not so sure...', 12, 0, 100, 1, 0, 0, 0, 0, 'Mojojuju - tarot card 1 (live, ep8 3:44:16)'),
(371917, 1, 0, 'Da Knife card. A rhetorical figure dat predicts betrayal in da journey ya about to undertake.', 12, 0, 100, 1, 0, 0, 0, 0, 'Mojojuju - tarot card 2 (live, ep8 3:44:22)'),
(371917, 2, 0, 'Da third and final card is... da Warrior? Pinch me, I can\'t believe it. Da tarot has never been so literal before.', 12, 0, 100, 1, 0, 0, 0, 0, 'Mojojuju - tarot card 3 (live, ep8 3:44:30)'),
(371931, 0, 0, 'Welcome to the edge of the faire! Need a map, a snack, or just a good excuse to escape?', 12, 0, 100, 0, 0, 0, 0, 0, 'Azzar Faire Assistant - player nearby (Rowan\'s video, Nov 2)'),
(371932, 0, 0, 'Thirsty, I bet. Well, we\'ve got drinks that\'ll knock your socks off-literally! No refunds!', 12, 0, 100, 0, 0, 0, 0, 0, 'Beach Bar Manager - player nearby'),
(371962, 0, 0, 'Oi, you got tickets? I got stuff! Step right up, before I change my mind!', 12, 0, 100, 0, 0, 0, 0, 0, 'Mega - player nearby'),
(371964, 0, 0, 'Ahhhhhh', 14, 0, 100, 0, 0, 0, 0, 0, 'Noggenfogger Mycologist - aggro (live)'),
(371965, 0, 0, 'Ahhhhhh', 14, 0, 100, 0, 0, 0, 0, 0, 'Noggenfogger Mycologist - aggro (live)'),
(372038, 0, 0, 'Y-You\'ve saved me! I thought I was gonna end up as a spider snack!', 12, 0, 100, 0, 0, 0, 0, 0, 'Erky - freed from a cocoon (live line, f12 0:13:45)'),
(372074, 0, 0, 'I wasn\'t trying to cause any trouble!', 12, 0, 100, 0, 0, 0, 0, 0, 'Drunken Reveler - on aggro (ep8 2:42:40)'),
(372074, 0, 1, 'Let me go! I can control myself, I swear.', 12, 0, 100, 0, 0, 0, 0, 0, 'Drunken Reveler - on aggro (ep8 2:42:40)'),
(372074, 0, 2, 'Hold on, I didn\'t mean it like that! Let\'s just forget it!', 12, 0, 100, 0, 0, 0, 0, 0, 'Drunken Reveler - on aggro (ep8 2:42:40)'),
(372074, 1, 0, 'I\'ll never touch alcohol again in my life!', 12, 0, 100, 0, 0, 0, 0, 0, 'Drunken Reveler - on death (ep8 2:42:40)'),
(372074, 1, 1, 'Alright, I got it! I\'m gone, don\'t worry!', 12, 0, 100, 0, 0, 0, 0, 0, 'Drunken Reveler - on death (ep8 2:42:40)'),
(372074, 1, 2, 'I\'m leaving, see? No need to hit me again!!', 12, 0, 100, 0, 0, 0, 0, 0, 'Drunken Reveler - on death (ep8 2:42:40)'),
