(372793, 0, 0, 'Thank the Light! I thought I was going to be spider food!', 12, 0, 20, 0, 0, 0, 0, 0, 'Rescued Faire-goer (OURS)'),
(372793, 0, 1, 'You got me out! First round at the Faire tavern is on me!', 12, 0, 20, 0, 0, 0, 0, 0, 'Rescued Faire-goer (OURS)'),
(372793, 0, 2, 'Never again am I taking the shortcut through these ruins...', 12, 0, 20, 0, 0, 0, 0, 0, 'Rescued Faire-goer (OURS)'),
(372793, 0, 3, 'Free! I\'m free! Which way is the Faire?!', 12, 0, 20, 0, 0, 0, 0, 0, 'Rescued Faire-goer (OURS)'),
(372793, 0, 4, 'Webs in my hair, but alive! Thank you, friend!', 12, 0, 20, 0, 0, 0, 0, 0, 'Rescued Faire-goer (OURS)');

