DELETE FROM `page_text` WHERE `ID` IN (51126, 51127, 60000);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `VerifiedBuild`) VALUES
(51126, 'Time has worn away the tablet, as if nature itself sought to forget its horrors. Despite the erosion, the faint outlines of a central, towering figure, summoned by the trolls, are still visible.$b$bThis was a sacrificial circle, and suddenly the realization hits you: the Faire now stands directly atop it. Even the eight ruined pillars are featured in the tablet\'s carvings.$b$bAlong the edges, the trolls are shown undergoing a dark metamorphosis.', 0, 12340),
(51127, '<A pile of remains covered in dust and dirt. They contain ceramics, stone tablets, and ritual utensils. The Tower must have served a religious purpose as a point of communication between the earthly and the divine. Judging by the deterioration of the structure, at least fifteen thousand years must have passed since its construction.>', 0, 12340),
(60000, 'Remains of an ancient Vrykul cathedral, built in honor of the Titans.$b$bThe folly of the trolls, despite the terror it unleashed, ignited the ascent of the brightest angel in Odyn\'s service and inspired the most epic song in Vrykul tradition. Even the magic of Helya, born of envy and rooted deep in the forest, could not eclipse the splendor of the ruined cathedral.', 0, 12340);

