INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(1650201, 1, 1, 'Got a ticket for me, $c? Step right up!', NULL),
(1650202, 1, 1, 'Hold still! The scanner needs a clean reading.', NULL),
(1650203, 1, 1, 'Seen all the hot spots yet? The tent, the fairgrounds, the beach bar, the roller coaster - go on, the workers don\'t bite.', NULL),
(1650213, 0, 1, 'No barrel, no deal, friend. Xoxis knows the rule: the booze rolls in, then the rewards roll out.', 12340),
(1650227, 0, 1, 'The mech is warmed up and the demon is not getting any friendlier. Get in there!', 12340),
(1650228, 0, 1, 'The Void is still waiting for you. It is... patient.', 12340),
(1650229, 0, 1, 'What are you standing around for? The track won\'t burn itself. Get in the kart!', 12340),
(1650230, 0, 1, 'Still here? Those ducks won\'t pluck themselves. Get in a cannon!', 12340),
(1650231, 0, 1, 'Back already? Those legs aren\'t shaking yet. Suit up and climb!', 12340),
(1650232, 0, 1, 'Still here? The little ones are waiting in the tent, and they are hungry. Off you go!', 12340),
(1650257, 0, 1, 'No barrel, no deal, friend. Xoxis knows the rule: the booze rolls in, then the rewards roll out.', 12340),
(1650266, 0, 1, 'The mech is warmed up and the demon is not getting any friendlier. Get in there!', 12340),
(1650267, 0, 1, 'The Void is still waiting for you. It is... patient.', 12340),
(1650268, 0, 1, 'What are you standing around for? The track won\'t burn itself. Get in the kart!', 12340),
(1650269, 0, 1, 'Still here? Those ducks won\'t pluck themselves. Get in a cannon!', 12340),
(1650270, 0, 1, 'Back already? Those legs aren\'t shaking yet. Suit up and climb!', 12340),
(1650273, 0, 1, 'Still here? The little ones are waiting in the tent, and they are hungry. Off you go!', 12340);

DELETE FROM `quest_offer_reward` WHERE `ID` IN (1650201, 1650202, 1650203, 1650204, 1650205, 1650213, 1650227, 1650228, 1650229, 1650230, 1650231, 1650232,
1650234, 1650238, 1650239, 1650257, 1650266, 1650267, 1650268, 1650269, 1650270, 1650273, 1650275, 1650276);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`,
`RewardText`, `VerifiedBuild`) VALUES
(1650201, 4, 0, 0, 0, 0, 0, 0, 0, 'A promotional ticket! Welcome, welcome, to the glorious Azzar Faire!$B$BGames, prizes, sun and sea - it\'s all here, and it\'s all for you. Take a look around, and come talk to me if you want to know what\'s on.', NULL),
(1650202, 4, 0, 0, 0, 0, 0, 0, 0, 'Scan\'s clean! You\'re officially welcome at the Azzar Faire. Here are some tickets on the house - spend them wisely... or don\'t, it\'s a faire!', NULL),
(1650203, 4, 0, 0, 0, 0, 0, 0, 0, 'Now you know your way around! Here, a little something for the legwork. Go have some fun!', NULL),
(1650204, 2, 0, 0, 0, 0, 0, 0, 0, 'Your face... I don\'t recognize it... That can only mean you are new to the Azzar Faire!$B$B<Gizmo enthusiastically shakes your hand and introduces himself.>$B$BWelcome, $N! I hope your experience here is absolutely fantastic. If you feel like it, have a snack and enjoy! Or not, it\'s up to you! Feel at home and do whatever you want. I\'ve designed this place so that fun has no limits!', NULL),
(1650205, 4, 0, 0, 0, 0, 0, 0, 0, 'Fantastic job! Now everyone proudly shows where they\'ve put a good part of their money.$B$BThank you very much, $N. Now dive into the faire and soak up every bit of the fun! Oh yes... and for that you\'ll need...$B$B<Gizmo rummages in one of his dozen pockets.>$B$BHere you go! See you around the attractions!', NULL),
(1650213, 4, 0, 0, 0, 0, 0, 0, 0, 'Well, look at that! One barrel, delivered in one piece... mostly. Xoxis always did have an eye for good help.$b$b<Zanket gives the barrel a fond pat.>$b$bHere, this is for your trouble. And if she ever sends another one my way, you know the road.', 12340),
(1650227, 4, 0, 0, 0, 0, 0, 0, 0, 'HA! Did you see that thing go down? Scrap metal and fel smoke everywhere!$b$b<Rikky punches the air.>$b$bThat is how you break the Bullet Romper. Here, you earned every bit of this.', 12340),
(1650228, 2, 0, 0, 0, 0, 0, 0, 0, 'You looked into it... and you came back.$b$b<Snagg studies your eyes for a long moment, as if searching for something left behind.>$b$bThe shadows speak well of you. Take this. My research owes you that much.', 12340),
(1650229, 4, 0, 0, 0, 0, 0, 0, 0, 'Ha! Smell that? Burnt rubber. That\'s the smell of somebody who didn\'t lift off the gas.$b$b<Brumm flicks the ash off his cigarette and nods.>$b$bNot bad for a first run, kid. Here, you earned it.', 12340),
(1650230, 4, 0, 0, 0, 0, 0, 0, 0, 'Ha! Look at all that soot on your face. Feathers everywhere, ego fully repaired.$b$b<Takk counts out your reward with a wide grin.>$b$bYou\'ve earned these. And remember: never trust a duck.', 12340),
(1650231, 4, 0, 0, 0, 0, 0, 0, 0, 'Look at you, still in one piece! I told you, the quickest workout on the whole island.$b$b<Belle hands you your reward with a wink.>$b$bCome back when your legs stop shaking.', 12340),
(1650232, 4, 0, 0, 0, 0, 0, 0, 0, 'Ha! Look at you, covered in feathers and banana.$b$b<Otto laughs and slaps his knee.>$b$bThe wonkas are safe, the crowd is happy, and my pockets are a little heavier. Everybody wins! Here, this is yours.', 12340),
(1650234, 1, 0, 0, 0, 0, 0, 0, 0, 'Take a spin, see what you win!$B$B<Nix rubs his hands together.>$B$BAnother daring soul! Come back whenever luck calls you. The Raffle Stand never closes.', NULL),
(1650238, 1, 0, 0, 0, 0, 0, 0, 0, 'Hold on a sec, just wanna make sure... Alright, perfect. What a haul!$B$BWith the rune thread, infernal stone, and portal rune, I\'ll be able to whip up something fantastic. Though, I\'m gonna need hundreds more runes, threads, and stones. Maybe even thousands. I\'ll still need you to sneak them into the faire, one a day shouldn\'t raise any eyebrows.$B$BHere is your reward. Hope we can keep this little arrangement going!', 12340),
(1650239, 1, 0, 0, 0, 0, 0, 0, 0, 'Hold on a sec, just wanna make sure... Alright, perfect. What a haul!$B$BWith the rune thread, infernal stone, and portal rune, I\'ll be able to whip up something fantastic. Though, I\'m gonna need hundreds more runes, threads, and stones. Maybe even thousands. I\'ll still need you to sneak them into the faire, one a day shouldn\'t raise any eyebrows.$B$BHere is your reward. Hope we can keep this little arrangement going!', 12340),
(1650257, 4, 0, 0, 0, 0, 0, 0, 0, 'Back again with another one of Xoxis\' runaways? At this rate I should put you on the payroll.$b$bHere\'s your cut. Don\'t drink it all in one place!', 12340),
(1650266, 4, 0, 0, 0, 0, 0, 0, 0, 'Back in one piece again! The mech likes you, I can tell. It only smokes a little.$b$bHere is your cut. Same time tomorrow?', 12340),
(1650267, 2, 0, 0, 0, 0, 0, 0, 0, 'Again you return. The echo grows fonder of you each time.$b$b<Snagg writes something down without looking away from you.>$b$bYour reward. Come back when the whispers call.', 12340),
(1650268, 4, 0, 0, 0, 0, 0, 0, 0, 'Back in one piece, and so is the kart. Mostly.$b$b<Brumm takes a long drag.>$b$bHere\'s your cut. Come back tomorrow, I\'ll have the tires warm.', 12340),
(1650269, 4, 0, 0, 0, 0, 0, 0, 0, 'Another flock plucked! The animatronics guild is going to file a complaint... again.$b$bHere\'s your cut. Come back tomorrow, they\'re already plotting their revenge.', 12340),
(1650270, 4, 0, 0, 0, 0, 0, 0, 0, 'Another climb done! My props survived, and so did you. That\'s a good day.$b$bHere\'s your reward. Same time tomorrow?', 12340),
(1650273, 4, 0, 0, 0, 0, 0, 0, 0, 'Back again, and the little ones still like you. That\'s more than I can say for my cousin\'s cooking.$b$bHere\'s your share. Come back tomorrow, they never stop being hungry.', 12340),
(1650275, 1, 0, 0, 0, 0, 0, 0, 0, 'Hold on a sec, just wanna make sure... Alright, perfect. What a haul!$B$BWith the rune thread, infernal stone, and portal rune, I\'ll be able to whip up something fantastic. Though, I\'m gonna need hundreds more runes, threads, and stones. Maybe even thousands. I\'ll still need you to sneak them into the faire, one a day shouldn\'t raise any eyebrows.$B$BHere is your reward. Hope we can keep this little arrangement going!', 12340),
(1650276, 1, 0, 0, 0, 0, 0, 0, 0, 'Hold on a sec, just wanna make sure... Alright, perfect. What a haul!$B$BWith the rune thread, infernal stone, and portal rune, I\'ll be able to whip up something fantastic. Though, I\'m gonna need hundreds more runes, threads, and stones. Maybe even thousands. I\'ll still need you to sneak them into the faire, one a day shouldn\'t raise any eyebrows.$B$BHere is your reward. Hope we can keep this little arrangement going!', 12340);

